/// Build a complete PLY header string for a 3DGS scene.
///
/// The header ends with `end_header\n`.
///
/// # Parameters
/// - `n_gaussians`: number of vertex elements.
/// - `sh_rest_count`: number of `f_rest_*` properties per Gaussian.
/// - `format`: the PLY format variant.
#[must_use]
pub fn ply_build_header(n_gaussians: usize, sh_rest_count: usize, format: PlyFormat) -> String {
    let mut h = String::with_capacity(2048);
    h.push_str("ply\n");
    h.push_str(&format!("format {} 1.0\n", format.as_ply_str()));
    h.push_str("comment Generated by OxiGAF (https://github.com/cool-japan/oxigaf)\n");
    h.push_str(&format!("element vertex {}\n", n_gaussians));
    for name in &["x", "y", "z"] {
        h.push_str(&format!("property float {}\n", name));
    }
    for name in &["nx", "ny", "nz"] {
        h.push_str(&format!("property float {}\n", name));
    }
    for i in 0..3 {
        h.push_str(&format!("property float f_dc_{}\n", i));
    }
    for i in 0..sh_rest_count {
        h.push_str(&format!("property float f_rest_{}\n", i));
    }
    h.push_str("property float opacity\n");
    for i in 0..3 {
        h.push_str(&format!("property float scale_{}\n", i));
    }
    for i in 0..4 {
        h.push_str(&format!("property float rot_{}\n", i));
    }
    h.push_str("end_header\n");
    h
}
