/// Infer SH degree from a rest coefficient count.
///
/// `n_rest = (d+1)^2 * 3 - 3`  ⟹  `(d+1)^2 = (n_rest + 3) / 3`.
///
/// Returns an error if `n_rest` does not correspond to a valid degree.
fn sh_degree_from_n_rest(n_rest: usize) -> Result<usize, PlyError> {
    if n_rest == 0 {
        return Ok(0);
    }
    let total = n_rest + 3;
    if !total.is_multiple_of(3) {
        return Err(PlyError::InvalidData(format!(
            "n_rest={} is not divisible by 3",
            n_rest
        )));
    }
    let sq = total / 3;
    let d_plus_1 = (sq as f64).sqrt().round() as usize;
    if d_plus_1 * d_plus_1 != sq {
        return Err(PlyError::InvalidData(format!(
            "n_rest={} does not correspond to a valid SH degree",
            n_rest
        )));
    }
    Ok(d_plus_1 - 1)
}
